import org.jsoup.Jsoup;
import org.jsoup.nodes.Document;
import org.jsoup.nodes.Element;
import org.jsoup.select.Elements;
import org.jsoup.select.Selector;
import org.jsoup.select.Evaluator;
import org.jsoup.select.Collector;

public class Probe {
    static int fails = 0;
    static void check(String name, Runnable r) {
        try { r.run(); System.out.println("PASS " + name); }
        catch (AssertionError e) { fails++; System.out.println("FAIL " + name + " :: " + e.getMessage()); }
        catch (Exception e) { fails++; System.out.println("ERROR " + name + " :: " + e); }
    }
    static void ids(String css, Document doc, String expected) {
        String got = doc.select(css).eachAttr("id").toString();
        if (!got.equals(expected)) throw new AssertionError(css + " got=" + got + " expected=" + expected);
    }
    static void tags(String css, Document doc, String expected) {
        String got = doc.select(css).stream().map(Element::tagName).reduce((a,b)->a+","+b).orElse("");
        if (!got.equals(expected)) throw new AssertionError(css + " got=" + got + " expected=" + expected);
    }
    public static void main(String[] args) {
        // 1. article:has(> img.hero) must NOT match on deeper img
        Document d1 = Jsoup.parse(
            "<article id=a1><div><img class=hero></div></article>" +
            "<article id=a2><img class=hero></article>" +
            "<article id=a3><img></article>");
        check("article:has(> img.hero)", () -> ids("article:has(> img.hero)", d1, "[a2]"));

        // 2. li:has(+ li.selected) only adjacent
        Document d2 = Jsoup.parse(
            "<ul><li id=l1>x</li><li>y</li><li class=selected>z</li></ul>" +
            "<ul><li id=l2>a</li><li class=selected>b</li></ul>");
        check("li:has(+ li.selected)", () -> ids("li:has(+ li.selected)", d2, "[l2]"));

        // 3. p:has(~ p.notice) allows intervening elements
        Document d3 = Jsoup.parse(
            "<div><p id=p1>a</p><h2>h</h2><p class=notice>n</p></div>" +
            "<div><p id=p2>a</p><p>mid</p></div>");
        check("p:has(~ p.notice)", () -> ids("p:has(~ p.notice)", d3, "[p1]"));
        // bare branch only descendants
        check("p:has(span) descendant only", () -> {
            Document d = Jsoup.parse("<p id=1><b><span>x</span></b></p><p id=2><span>y</span></p>");
            ids("p:has(span)", d, "[1, 2]");
        });
        // mixed comma: > child and descendant in one list
        check("div:has(> img, span b)", () -> {
            Document d = Jsoup.parse(
                "<div id=d1><img></div>" +
                "<div id=d2><p><span><b>x</b></span></p></div>" +
                "<div id=d3><div><img></div></div>");
            ids("div:has(> img, span b)", d, "[d1, d2]");
        });
        // sibling + descendant mixed, dedupe doc order
        check("div:has(> i, em) dedupe/order", () -> {
            Document d = Jsoup.parse(
                "<div id=a><i></i><em></em></div>" +
                "<div id=b><em></em></div>" +
                "<div id=c><i></i></div>");
            ids("div:has(> i, em)", d, "[a, b, c]");
        });
        // anchor must not drift: div:has(section > p) — p must be descendant of anchor div, section between
        check("div:has(section > p)", () -> {
            Document d = Jsoup.parse(
                "<div id=1><section><p>x</p></section></div>" +
                "<div id=2><section><div><p>deep</p></div></section></div>");
            ids("div:has(section > p)", d, "[1]");
        });
        // + then descendant chain: li:has(+ li.selected em)? relative + then space
        check("article:has(+ article > img.hero)", () -> {
            Document d = Jsoup.parse(
                "<article id=a1></article><article><div><img class=hero></div></article>" +
                "<article id=a2></article><article><img class=hero></article>");
            ids("article:has(+ article > img.hero)", d, "[a2]");
        });
        // nested has anchor: article:has(> div:has(> img.hero)) strict children both levels
        check("nested > > strict", () -> {
            Document d = Jsoup.parse(
                "<article id=a1><div><section><img class=hero></section></div></article>" +
                "<article id=a2><div><img class=hero></div></article>");
            ids("article:has(> div:has(> img.hero))", d, "[a2]");
        });
        // non-element nodes don't count for + sibling
        check("+: text nodes ignored", () -> {
            Document d = Jsoup.parse("<div><p id=1>a</p> some text <p class=x>b</p></div>");
            ids("p:has(+ p.x)", d, "[1]");
        });
        // errors
        check(":has() empty", () -> expectParseError(":has()"));
        check(":has(>) dangling", () -> expectParseError("div:has(>)"));
        check(":has( unclosed", () -> expectParseError("div:has(p"));
        check(":has(:bogus())", () -> expectParseError("div:has(:bogus)"));
        check(":has(p >)", () -> expectParseError("div:has(p >)"));
        check(":has(,) empty branches", () -> expectParseError("div:has(,)"));
        // mutation re-eval, no caching
        check("mutation re-eval", () -> {
            Document d = Jsoup.parse("<div id=d><section><img class=hero></section></div>");
            ids("div:has(> img.hero)", d, "[]");
            d.selectFirst("section").appendElement("img").attr("class", "hero"); // still not direct
            ids("div:has(> img.hero)", d, "[]");
            Element img = d.selectFirst("img.hero").remove();
            d.selectFirst("div").appendChild(img); // now direct child
            ids("div:has(> img.hero)", d, "[d]");
            // repeat stability
            ids("div:has(> img.hero)", d, "[d]");
        });
        // compiled evaluator reused across mutation
        check("compiled eval reused after mutation", () -> {
            Document d = Jsoup.parse("<div id=d><img class=hero></div>");
            Evaluator eval = QueryParserParse("div:has(> img.hero)");
            Elements one = Collector.collect(eval, d);
            if (!one.eachAttr("id").equals("[d]")) throw new AssertionError("initial");
            d.selectFirst("img").remove();
            Elements two = Collector.collect(eval, d);
            if (!two.eachAttr("id").equals("[]")) throw new AssertionError("after remove: " + two.eachAttr("id"));
        });
        // sibling non-element for ~ via comments
        check("~ ignores comments/text", () -> {
            Document d = Jsoup.parse("<div><p id=1>a</p><!-- c --><p class=notice>n</p></div>");
            ids("p:has(~ p.notice)", d, "[1]");
        });
        // anchor itself must not match: div:has(div) should not include anchor without descendant div
        check("self not matched", () -> {
            Document d = Jsoup.parse("<div id=outer><div id=inner>x</div></div>");
            ids("div:has(div)", d, "[outer]");
        });
        // relative combinators inside nested :is
        check("has(> :is(div, span))", () -> {
            Document d = Jsoup.parse("<section id=s1><div></div></section><section id=s2><p><span></span></p></section>");
            ids("section:has(> :is(div, span))", d, "[s1]");
        });
        System.out.println(fails == 0 ? "ALL OK" : fails + " FAILURES");
        System.exit(fails == 0 ? 0 : 1);
    }
    static Evaluator QueryParserParse(String q) throws Exception {
        return (Evaluator) Class.forName("org.jsoup.select.QueryParser")
            .getMethod("parse", String.class).invoke(null, q);
    }
    static void expectParseError(String css) {
        try {
            Evaluator e = QueryParserParse(css);
            throw new AssertionError("no error, parsed: " + e);
        } catch (ReflectiveOperationException roe) {
            throw new AssertionError(roe.toString());
        } catch (java.lang.reflect.InvocationTargetException ite) {
            // impossible ordering above; keep
        } catch (Selector.SelectorParseException ok) {}
          catch (RuntimeException re) {
            if (re.getClass().getName().contains("SelectorParseException")) return;
            throw new AssertionError("wrong exception: " + re);
        }
    }
}
