import org.jsoup.Jsoup;
import org.jsoup.nodes.Document;
public class Dbg4 {
    public static void main(String[] a) {
        // internal '+' (not leading) in :has() must stay in anchor's descendants
        Document d = Jsoup.parse("<span></span><div id=x></div><span></span><a></a>");
        System.out.println("div:has(span + a) => " + d.select("div:has(span + a)").eachAttr("id") + " (want [] )");
        // internal '~'
        Document d2 = Jsoup.parse("<div id=x></div><p></p><em></em><p class=notice></p>");
        System.out.println("div:has(p ~ p.notice) => " + d2.select("div:has(p ~ p.notice)").eachAttr("id") + " (want [] )");
        // internal '>'
        Document d3 = Jsoup.parse("<div id=x></div><section><img class=hero></section>");
        System.out.println("div:has(section > img.hero) => " + d3.select("div:has(section > img.hero)").eachAttr("id") + " (want [] )");
        // leading ~ then internal +
        Document d4 = Jsoup.parse("<div id=x></div><p></p><span></span><em></em>");
        System.out.println("div:has(~ p span + em) => " + d4.select("div:has(~ p span + em)").eachAttr("id"));
        // does internal + sibling case hit descendants properly too
        Document d5 = Jsoup.parse("<div id=ok><span></span><a></a></div><span></span><div id=bad></div><a></a>");
        System.out.println("div:has(span + a) mixed => " + d5.select("div:has(span + a)").eachAttr("id") + " (want [ok])");
    }
}
