     * Match a {@code +}/{@code ~} branch against each following element sibling in turn (element nodes only), and
     * within that sibling's subtree. The sibling element is supplied as the matching root, so the branch's leading
     * sibling edge (whose left side is the synthetic Root) resolves to the anchor; {@code +} is satisfied only by
     * the immediate sibling, {@code ~} by any later sibling. Further chained combinators reach into the subtree.
     */
    private static boolean matchesFollowingSiblings(Element anchor, Evaluator branch) {
        NodeIterator<Node> it = NodeIterPool.borrow();
        try {
            for (Element sibling = anchor.nextElementSibling(); sibling != null;
                 sibling = sibling.nextElementSibling()) {
                it.restart(sibling);
                while (it.hasNext()) {
                    Node node = it.next();
                    if (branch.matches(sibling, node)) return true;
                }
            }
        } finally {
            NodeIterPool.release(it);
        }
        return false;
    }

    @Override
    boolean evaluateMatch(Element root, Node node) {
        return false; // unused; :has(::comment)) goes via implicit root combinator
    }

    /**
     * Determine a branch's leading sibling axis, if any. Only a leading {@code +} or {@code ~} is compiled against
     * the synthetic {@link Root} (the anchor); an internal sibling combinator references a real selector and so is
     * scoped to the anchor's descendants, never to its own siblings.
     * @return {@code '+'}, {@code '~'}, or {@code 0} for a descendant-only branch
     */
    private static char siblingAxis(Evaluator branch) {
        if (branch instanceof CombiningEvaluator) {
            for (Evaluator inner : ((CombiningEvaluator) branch).evaluators) {
                if (inner instanceof ImmediatePreviousSibling && ((StructuralEvaluator) inner).evaluator instanceof Root)
                    return '+';
                if (inner instanceof PreviousSibling && ((StructuralEvaluator) inner).evaluator instanceof Root)
                    return '~';
            }
        }
        return 0;
    }

    @Override protected int cost() {
        return 10 * evaluator.cost();
    }

    @Override
    public String toString() {
        return String.format(":has(%s)", evaluator);
    }
}

