import org.jsoup.Jsoup;
import org.jsoup.nodes.Document;
import org.jsoup.nodes.Element;
import org.jsoup.select.*;
public class Probe2 {
    static int fails=0;
    static void ids(String css, Document doc, String expected) {
        String got = doc.select(css).eachAttr("id").toString();
        System.out.println((got.equals(expected)?"PASS ":"FAIL ")+css+" => "+got+(got.equals(expected)?"":" expected "+expected));
        if(!got.equals(expected)) fails++;
    }
    public static void main(String[] a){
        // chained sibling in later sibling: div:has(+ p + img)
        ids("div:has(+ p + img)", Jsoup.parse("<div id=a></div><p></p><img>"), "[a]");
        // but not when img not after an immediately-adjacent p
        ids("div:has(+ p + img) 2", Jsoup.parse("<div id=a></div><p></p><h2></h2><img>"), "[]");
        // + p ~ img (general later)
        ids("div:has(+ p ~ img)", Jsoup.parse("<div id=a></div><p></p><h2></h2><img>"), "[a]");
        // + article > img.hero (descendant in immediate sibling's subtree)
        ids("article:has(+ article > img.hero)", Jsoup.parse(
            "<article id=a1></article><article><div><img class=hero></div></article><article id=a2></article><article><img class=hero></article>"), "[a2]");
        // ~ p span: target in a later sibling's subtree, intervening elements allowed
        ids("div:has(~ p span)", Jsoup.parse("<div id=a></div><h2></h2><p><span id=x></span></p>"), "[a]");
        // ~ p span must NOT match span that is p's sibling in anchor's subtree
        ids("div:has(~ p span) 2", Jsoup.parse("<div id=a><p></p><span></span></div>"), "[]");
