        // mutation with sibling
        Document d = Jsoup.parse("<div id=d></div><h1></h1>");
        ids("div:has(+ h1)", d, "[d]");
        d.selectFirst("h1").remove();
        ids("div:has(+ h1) removed", d, "[]");
        d.selectFirst("div").after("<h1></h1>");
        ids("div:has(+ h1) added", d, "[d]");
        // compiled evaluator reused across mutation
        Evaluator ev = QueryParser.parse("div:has(> section)");
        Document d2 = Jsoup.parse("<div id=x><section></section></div>");
        System.out.println(Collector.collect(ev,d2).eachAttr("id") + " / reset&rematch ");
        d2.selectFirst("section").remove();
        System.out.println(Collector.collect(ev,d2).eachAttr("id")+" (want [])");
        System.out.println(fails==0?"ALL OK":fails+" FAIL");
        System.exit(fails==0?0:1);
    }
