import org.jsoup.Jsoup;
import org.jsoup.nodes.Document;
public class Probe3 {
    static int fails=0;
    static void ids(String css, Document doc, String expected) {
        String got = doc.select(css).eachAttr("id").toString();
        System.out.println((got.equals(expected)?"PASS ":"FAIL ")+css+" => "+got+(got.equals(expected)?"":" expected "+expected));
        if(!got.equals(expected)) fails++;
    }
    public static void main(String[] a){
        // + adjacency enforced even though deep search scans all following siblings
        ids("div:has(+ section p)", Jsoup.parse("<div id=x></div><section><p></p></section>"), "[x]");
        ids("div:has(+ section p) intervening", Jsoup.parse("<div id=x></div><h1></h1><section><p></p></section>"), "[]");
        // ~ p span + em positive
        ids("div:has(~ p span + em)", Jsoup.parse("<div id=x></div><p><span></span><em></em></p>"), "[x]");
        // + p.selected: only immediate
        ids("div:has(+ p.x)", Jsoup.parse("<div id=a></div><p class=x></p><div id=b></div><h></h><p class=x></p>"), "[a]");
        // ~ p.x: any later
        ids("div:has(~ p.x)", Jsoup.parse("<div id=a></div><h></h><p class=x></p><div id=b></div>"), "[a]");
        // nested :has with sibling anchor stability
        ids("section:has(article:has(+ h2))", Jsoup.parse(
            "<section id=s1><article id=a1></article><h2></h2></section><section id=s2><article id=a2><span></span></article></section>"), "[s1]");
        // :has sibling combined with ordinary selector
        ids("div.foo:has(+ p)", Jsoup.parse("<div class=foo id=a></div><p></p><div class=bar id=b></div><p></p>"), "[a]");
        // text/comment nodes between do not break adjacency
        ids("p:has(+ b)", Jsoup.parse("<div><p id=1>a</p> txt <!--c--> <b>b</b></div>"), "[1]");
        // same element matches multiple branches -> once, doc order
        ids("div:has(+ p, ~ p)", Jsoup.parse("<div id=a></div><p></p><div id=b></div><h></h><p></p>"), "[a, b]");
        // sibling branch where anchor is root element (no siblings) -> no error, no match
        ids("html:has(~ body)", Jsoup.parse("<html><head></head><body></body></html>"), "[]");
        // leading combinator with :is() inside
        ids("div:has(+ :is(p.x, a))", Jsoup.parse("<div id=a></div><p class=x></p><div id=b></div><a></a>"), "[a, b]");
        System.out.println(fails==0?"ALL OK":fails+" FAIL");
        System.exit(fails==0?0:1);
    }
}
