import org.jsoup.Jsoup;
public class Probe4 {
    static int fails=0;
    static void ids(String css, String html, String expected){
        String got=Jsoup.parse(html).select(css).eachAttr("id").toString();
        System.out.println((got.equals(expected)?"PASS ":"FAIL ")+css+" => "+got+(got.equals(expected)?"":" expected "+expected));
        if(!got.equals(expected))fails++;
    }
    public static void main(String[] x){
        // :is() with internal combinator moves target into sibling's subtree
        ids("div:has(+ p:is(b > i))", "<div id=a></div><p><b><i></i></b></p>", "[a]");
        ids("div:has(+ p:is(b i))", "<div id=a></div><p><b><i></i></b></p>", "[a]");
        // nested :has stays a condition ON the sibling element (shallow is correct)
        ids("div:has(+ p:has(i))", "<div id=a></div><p><i></i></p>", "[a]");
        ids("div:has(+ p:has(i)) none", "<div id=a></div><p><b></b></p>", "[]");
        // :not is self-contained (target remains sibling)
        ids("div:has(+ p:not(.x))", "<div id=a></div><p class=y></p>", "[a]");
        ids("div:has(+ p:not(.x)) no", "<div id=a></div><p class=x></p>", "[]");
        System.out.println(fails==0?"ALL OK":fails+" FAIL");
        System.exit(fails==0?0:1);
    }
}
