import org.jsoup.Jsoup;
import org.jsoup.nodes.Document;
import org.jsoup.select.*;
import java.util.concurrent.*;
import java.util.concurrent.atomic.AtomicInteger;
public class Concurrency {
    public static void main(String[] a) throws Exception {
        Evaluator eval = QueryParser.parse("div:has(> img.hero, + p.note)");
        AtomicInteger ok = new AtomicInteger();
        int n=8, iters=2000;
        ExecutorService ex = Executors.newFixedThreadPool(n);
        CountDownLatch start = new CountDownLatch(1);
        for (int t=0;t<n;t++) ex.submit(() -> {
            try {
                for (int i=0;i<iters;i++) {
                    Document d = Jsoup.parse(
                        "<div id=x><img class=hero></div><div></div><p class=note></p>");
                    // mutate: remove the child img on some iterations
                    if (i % 2 == 0) d.selectFirst("img").remove();
                    boolean hitX = Collector.collect(eval, d).eachAttr("id").contains("x");
                    if (hitX == (i % 2 != 0)) ok.incrementAndGet();
                }
            } catch (Throwable th) { th.printStackTrace(); }
        });
        start.countDown();
        ex.shutdown();
        ex.awaitTermination(30, TimeUnit.SECONDS);
        int want = n*iters;
        System.out.println("ok="+ok.get()+"/"+want+(ok.get()==want?" CONCURRENCY OK":" MISMATCH"));
        System.exit(ok.get()==want?0:1);
    }
}
